from typing import Optional
from datetime import datetime
from pydantic import BaseModel, Field, ValidationError, EmailStr

# Define the typed model
class UserRequest(BaseModel):
    name: str = Field(..., min_length=2, max_length=50)
    email: EmailStr
    age: int = Field(..., ge=0, le=150)
    is_active: bool = True
    created_at: Optional[datetime] = None
    tags: list[str] = Field(default_factory=list, max_length=10)

def parse_request_body(data: dict) -> UserRequest:
    """Parse and validate request body into UserRequest model."""
    try:
        return UserRequest(**data)
    except ValidationError as e:
        # Format error messages for better readability
        errors = []
        for error in e.errors():
            field = ".".join(str(x) for x in error["loc"])
            errors.append(f"{field}: {error['msg']}")
        raise ValueError(f"Invalid request body: {'; '.join(errors)}")

# Example usage
if __name__ == "__main__":
    # Valid request
    valid_body = {
        "name": "John Doe",
        "email": "john@example.com",
        "age": 30,
        "is_active": True,
        "tags": ["user", "admin"]
    }

    try:
        user = parse_request_body(valid_body)
        print(f"Valid user: {user}")
    except ValueError as e:
        print(f"Error: {e}")

    # Invalid request (missing required field, invalid email, age out of range)
    invalid_body = {
        "name": "J",  # too short
        "email": "not-an-email",
        "age": 200,  # out of range
        "tags": ["a" * 100]  # too long
    }

    try:
        user = parse_request_body(invalid_body)
        print(f"Valid user: {user}")
    except ValueError as e:
        print(f"Error: {e}")

"""Shared helpers (io, formatting) used across tasks."""

import os
import sys
from pathlib import Path


def read_file(path):
    """Read a file and return its contents as bytes."""
    with open(path, 'rb') as f:
        return f.read()


def write_file(path, data):
    """Write bytes to a file."""
    with open(path, 'wb') as f:
        f.write(data)


def get_file_size(path):
    """Get file size in bytes."""
    return os.path.getsize(path)


def format_bytes(size):
    """Format byte size into human-readable string."""
    for unit in ['B', 'KB', 'MB', 'GB']:
        if size < 1024.0:
            return f"{size:.1f} {unit}"
        size /= 1024.0
    return f"{size:.1f} TB"


def validate_file_exists(path):
    """Validate that a file exists and is readable."""
    if not os.path.exists(path):
        raise FileNotFoundError(f"File not found: {path}")
    if not os.path.isfile(path):
        raise ValueError(f"Not a file: {path}")
    if not os.access(path, os.R_OK):
        raise PermissionError(f"File not readable: {path}")


def validate_output_path(path):
    """Validate that output path is writable."""
    parent = os.path.dirname(os.path.abspath(path))
    if not os.path.exists(parent):
        raise FileNotFoundError(f"Output directory not found: {parent}")
    if not os.access(parent, os.W_OK):
        raise PermissionError(f"Output directory not writable: {parent}")

def print_table(records, headers=None):
    """Print a list of records as an aligned table."""
    if not records:
        print("No records to display")
        return

    # Determine headers if not provided
    if headers is None:
        headers = list(records[0].keys())

    # Calculate column widths
    col_widths = [len(h) for h in headers]
    for record in records:
        for i, header in enumerate(headers):
            value = str(record.get(header, ''))
            col_widths[i] = max(col_widths[i], len(value))

    # Print header row
    header_line = ' | '.join(h.ljust(col_widths[i]) for i, h in enumerate(headers))
    print(header_line)
    print('-' * len(header_line))

    # Print data rows
    for record in records:
        row = ' | '.join(
            str(record.get(header, '')).ljust(col_widths[i])
            for i, header in enumerate(headers)
        )
        print(row)

# Example usage
if __name__ == "__main__":
    # Sample data
    records = [
        {"name": "Alice", "age": 30, "city": "New York"},
        {"name": "Bob", "age": 25, "city": "Los Angeles"},
        {"name": "Charlie", "age": 35, "city": "Chicago"},
        {"name": "David", "age": 28, "city": "Houston"}
    ]

    print_table(records)

