"""Shared helpers (io, formatting) used across tasks."""

import os
import sys
from pathlib import Path
from typing import Optional, Union


def read_file(path: Union[str, Path]) -> str:
    """Read a text file and return its contents."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()


def write_file(path: Union[str, Path], content: str) -> None:
    """Write content to a text file."""
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)


def ensure_output_dir(path: Union[str, Path]) -> Path:
    """Ensure the parent directory of a file path exists."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    return path


def validate_input_file(path: Union[str, Path]) -> Path:
    """Validate that an input file exists and is readable."""
    path = Path(path)
    if not path.exists():
        sys.exit(f"Error: Input file '{path}' does not exist.")
    if not path.is_file():
        sys.exit(f"Error: '{path}' is not a file.")
    return path


def get_output_path(input_path: Union[str, Path], 
                    output_path: Optional[str] = None,
                    suffix: str = "_grayscale") -> Path:
    """Generate an output path based on input path and optional output path."""
    input_path = Path(input_path)

    if output_path:
        return ensure_output_dir(output_path)

    # Generate default output path with suffix
    output = input_path.with_name(f"{input_path.stem}{suffix}{input_path.suffix}")
    return ensure_output_dir(output)


def format_bytes(size: int) -> str:
    """Format bytes into human-readable string."""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size < 1024.0:
            return f"{size:.1f} {unit}"
        size /= 1024.0
    return f"{size:.1f} PB"


def print_success(message: str) -> None:
    """Print a success message."""
    print(f"✓ {message}")


def print_error(message: str) -> None:
    """Print an error message to stderr."""
    print(f"✗ {message}", file=sys.stderr)

import bcrypt
import sqlite3
from typing import Optional

class PasswordManager:
    def __init__(self, db_path: str = "users.db"):
        self.db_path = db_path
        self.init_db()

    def init_db(self):
        """Initialize database with users table"""
        with sqlite3.connect(self.db_path) as conn:
            conn.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    password_hash TEXT NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            ''')

    def create_user(self, username: str, password: str) -> bool:
        """Create a new user with hashed password"""
        try:
            hashed = self.hash_password(password)
            with sqlite3.connect(self.db_path) as conn:
                conn.execute(
                    "INSERT INTO users (username, password_hash) VALUES (?, ?)",
                    (username, hashed.decode('utf-8'))
                )
            return True
        except sqlite3.IntegrityError:
            # Username already exists
            return False

    def authenticate(self, username: str, password: str) -> bool:
        """Authenticate a user"""
        with sqlite3.connect(self.db_path) as conn:
            cursor = conn.execute(
                "SELECT password_hash FROM users WHERE username = ?",
                (username,)
            )
            result = cursor.fetchone()

            if result is None:
                return False

            stored_hash = result[0].encode('utf-8')
            return self.verify_password(password, stored_hash)

    @staticmethod
    def hash_password(password: str) -> bytes:
        """Hash password with bcrypt"""
        salt = bcrypt.gensalt(rounds=12)  # 12 rounds is a good balance
        return bcrypt.hashpw(password.encode('utf-8'), salt)

    @staticmethod
    def verify_password(password: str, hashed_password: bytes) -> bool:
        """Verify password against hash"""
        try:
            return bcrypt.checkpw(password.encode('utf-8'), hashed_password)
        except ValueError:
            return False

