import argparse
import csv
import json
import sys
from typing import Any, Dict, List, Sequence

from .utils import print_table


def table_command(args: argparse.Namespace) -> None:
    """Print records as an aligned table."""
    records = []

    if args.file:
        # Read from file
        with open(args.file, "r") as f:
            if args.file.endswith(".csv"):
                reader = csv.reader(f)
                if args.header:
                    headers = next(reader)
                else:
                    headers = None
                records = list(reader)
            elif args.file.endswith(".json"):
                data = json.load(f)
                if isinstance(data, list):
                    if args.header and data and isinstance(data[0], dict):
                        headers = list(data[0].keys())
                        records = [list(row.values()) for row in data]
                    else:
                        headers = None
                        records = data
                else:
                    print("Error: JSON file must contain a list of records", file=sys.stderr)
                    sys.exit(1)
            else:
                # Assume plain text with delimiter
                delimiter = args.delimiter or "\t"
                for line in f:
                    line = line.strip()
                    if line:
                        records.append(line.split(delimiter))
                headers = None
    else:
        # Read from stdin
        if args.delimiter:
            for line in sys.stdin:
                line = line.strip()
                if line:
                    records.append(line.split(args.delimiter))
            headers = None
        else:
            # Parse JSON from stdin
            try:
                data = json.load(sys.stdin)
                if isinstance(data, list):
                    if args.header and data and isinstance(data[0], dict):
                        headers = list(data[0].keys())
                        records = [list(row.values()) for row in data]
                    else:
                        headers = None
                        records = data
                else:
                    print("Error: Input must be a JSON array", file=sys.stderr)
                    sys.exit(1)
            except json.JSONDecodeError:
                print("Error: Invalid JSON input", file=sys.stderr)
                sys.exit(1)

    if not records:
        print("No records found", file=sys.stderr)
        sys.exit(1)

    print_table(records, headers, args.max_width)


def register_table_parser(subparsers) -> None:
    """Register the table command parser."""
    parser = subparsers.add_parser(
        "table",
        help="Print records as an aligned table",
        description="Print records from file or stdin as an aligned table",
    )
    parser.add_argument(
        "-f", "--file",
        help="Input file (CSV, JSON, or delimited text). If not specified, reads from stdin."
    )
    parser.add_argument(
        "-d", "--delimiter",
        help="Delimiter for text files (default: tab for text, comma for CSV)"
    )
    parser.add_argument(
        "-H", "--header",
        action="store_true",
        help="Treat first row as header (for CSV) or use dict keys as headers (for JSON)"
    )
    parser.add_argument(
        "-w", "--max-width",
        type=int,
        default=80,
        help="Maximum table width (default: 80)"
    )
    parser.set_defaults(func=table_command)

