import phonenumbers
from phonenumbers import PhoneNumberFormat

class PhoneNumberHandler:
    def __init__(self, default_country="US"):
        self.default_country = default_country

    def validate(self, number):
        """Validate a phone number"""
        try:
            parsed = phonenumbers.parse(number, self.default_country)
            return phonenumbers.is_valid_number(parsed)
        except phonenumbers.NumberParseException:
            return False

    def format_international(self, number):
        """Format to international format"""
        try:
            parsed = phonenumbers.parse(number, self.default_country)
            if phonenumbers.is_valid_number(parsed):
                return phonenumbers.format_number(parsed, PhoneNumberFormat.INTERNATIONAL)
        except phonenumbers.NumberParseException:
            pass
        return None

    def format_e164(self, number):
        """Format to E.164 format (for storage)"""
        try:
            parsed = phonenumbers.parse(number, self.default_country)
            if phonenumbers.is_valid_number(parsed):
                return phonenumbers.format_number(parsed, PhoneNumberFormat.E164)
        except phonenumbers.NumberParseException:
            pass
        return None

    def get_country_code(self, number):
        """Extract country code"""
        try:
            parsed = phonenumbers.parse(number, self.default_country)
            return parsed.country_code
        except phonenumbers.NumberParseException:
            return None

