from typing import Type, TypeVar, Any, Dict
from pydantic import BaseModel, ValidationError
from fastapi import HTTPException, status
import json

T = TypeVar('T', bound=BaseModel)

def parse_and_validate(
    request_body: Any,
    model_class: Type[T],
    *,
    strict: bool = False
) -> T:
    """
    Parse and validate a request body into a typed Pydantic model.

    Args:
        request_body: The raw request body (dict, JSON string, or bytes)
        model_class: The Pydantic model class to validate against
        strict: If True, reject unknown fields (default: False)

    Returns:
        An instance of the model_class with validated data

    Raises:
        HTTPException: 400 Bad Request if validation fails
        HTTPException: 422 Unprocessable Entity if parsing fails
    """

    # Handle different input types
    try:
        if isinstance(request_body, bytes):
            # Try to decode bytes as JSON
            try:
                data = json.loads(request_body.decode('utf-8'))
            except json.JSONDecodeError as e:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"Invalid JSON format: {str(e)}"
                )
        elif isinstance(request_body, str):
            # Try to parse string as JSON
            try:
                data = json.loads(request_body)
            except json.JSONDecodeError as e:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"Invalid JSON format: {str(e)}"
                )
        elif isinstance(request_body, dict):
            data = request_body
        else:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail=f"Unsupported request body type: {type(request_body).__name__}"
            )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=f"Failed to parse request body: {str(e)}"
        )

    # Validate against the model
    try:
        if strict:
            # Use model_validate with strict mode
            return model_class.model_validate(data, strict=True)
        else:
            return model_class.model_validate(data)
    except ValidationError as e:
        # Format validation errors for better API responses
        errors = []
        for error in e.errors():
            error_dict = {
                "field": ".".join(str(loc) for loc in error["loc"]),
                "message": error["msg"],
                "type": error["type"]
            }
            if "input" in error:
                error_dict["received"] = error["input"]
            errors.append(error_dict)

        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail={
                "message": "Validation failed",
                "errors": errors
            }
        )
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=f"Validation error: {str(e)}"
        )


def parse_and_validate_optional(
    request_body: Any,
    model_class: Type[T],
    *,
    default: T = None
) -> T:
    """
    Parse and validate an optional request body.
    Returns default if body is empty/None.
    """
    if request_body is None or (isinstance(request_body, str) and not request_body.strip()):
        return default

    return parse_and_validate(request_body, model_class)


