from typing import Any, Dict, List, Optional, Type, TypeVar, Union
from datetime import datetime, date
from enum import Enum
import json
from dataclasses import dataclass, field, fields, is_dataclass
import re

T = TypeVar('T', bound='BaseModel')

class ValidationError(Exception):
    """Custom exception for validation errors"""
    def __init__(self, errors: Dict[str, str]):
        self.errors = errors
        super().__init__(f"Validation failed: {errors}")

class BaseModel:
    """Base class for all models with validation and parsing capabilities"""

    @classmethod
    def from_dict(cls: Type[T], data: Dict[str, Any]) -> T:
        """Parse and validate a dictionary into a model instance"""
        if not isinstance(data, dict):
            raise ValidationError({"__root__": "Expected a JSON object"})

        errors = {}
        parsed_data = {}

        # Get all fields from the dataclass
        model_fields = fields(cls)
        field_names = {f.name for f in model_fields}

        # Check for unknown fields
        unknown_fields = set(data.keys()) - field_names
        if unknown_fields:
            for field_name in unknown_fields:
                errors[field_name] = f"Unknown field: {field_name}"

        # Parse each known field
        for field_info in model_fields:
            field_name = field_info.name
            field_type = field_info.type
            field_default = field_info.default

            # Check if field is required
            if field_name not in data:
                if field_default is not field_info.default:
                    # Field has a default value
                    parsed_data[field_name] = field_default
                elif field_info.default_factory is not None:
                    # Field has a default factory
                    parsed_data[field_name] = field_info.default_factory()
                elif field_info.metadata.get('required', False):
                    errors[field_name] = f"Missing required field: {field_name}"
                else:
                    # Optional field without default
                    parsed_data[field_name] = None
                continue

            # Parse and validate the field value
            try:
                parsed_value = cls._parse_value(
                    data[field_name], 
                    field_type, 
                    field_name,
                    field_info.metadata
                )
                parsed_data[field_name] = parsed_value
            except ValidationError as e:
                errors.update(e.errors)

        if errors:
            raise ValidationError(errors)

        return cls(**parsed_data)

    @classmethod
    def _parse_value(cls, value: Any, expected_type: Type, field_name: str, metadata: Dict) -> Any:
        """Parse and validate a single value based on its expected type"""

        # Handle Optional types
        if hasattr(expected_type, '__origin__') and expected_type.__origin__ is Union:
            # Check if None is allowed
            if type(None) in expected_type.__args__:
                if value is None:
                    return None
                # Get the non-None type
                non_none_types = [t for t in expected_type.__args__ if t is not type(None)]
                if len(non_none_types) == 1:
                    expected_type = non_none_types[0]
                else:
                    # Try each type
                    for t in non_none_types:
                        try:
                            return cls._parse_value(value, t, field_name, metadata)
                        except ValidationError:
                            continue
                    raise ValidationError({field_name: f"Invalid value for field {field_name}"})

        # Handle List types
        if hasattr(expected_type, '__origin__') and expected_type.__origin__ is list:
            if not isinstance(value, list):
                raise ValidationError({field_name: f"Expected a list for field {field_name}"})

            item_type = expected_type.__args__[0]
            parsed_list = []
            for i, item in enumerate(value):
                try:
                    parsed_item = cls._parse_value(item, item_type, f"{field_name}[{i}]", metadata)
                    parsed_list.append(parsed_item)
                except ValidationError as e:
                    raise ValidationError({field_name: f"Invalid item at index {i}: {e.errors}"})
            return parsed_list

        # Handle Dict types
        if hasattr(expected_type, '__origin__') and expected_type.__origin__ is dict:
            if not isinstance(value, dict):
                raise ValidationError({field_name: f"Expected a dictionary for field {field_name}"})

            key_type, value_type = expected_type.__args__
            parsed_dict = {}
            for key, val in value.items():
                try:
                    parsed_key = cls._parse_value(key, key_type, f"{field_name}.key", metadata)
                    parsed_val = cls._parse_value(val, value_type, f"{field_name}.{key}", metadata)
                    parsed_dict[parsed_key] = parsed_val
                except ValidationError as e:
                    raise ValidationError({field_name: f"Invalid dictionary entry: {e.errors}"})
            return parsed_dict

        # Handle Enum types
        if isinstance(expected_type, type) and issubclass(expected_type, Enum):
            try:
                return expected_type(value)
            except ValueError:
                valid_values = [e.value for e in expected_type]
                raise ValidationError({field_name: f"Invalid enum value. Expected one of: {valid_values}"})

        # Handle datetime types
        if expected_type is datetime:
            if isinstance(value, datetime):
                return value
            if isinstance(value, str):
                try:
                    return datetime.fromisoformat(value.replace('Z', '+00:00'))
                except ValueError:
                    raise ValidationError({field_name: f"Invalid datetime format for field {field_name}"})
            raise ValidationError({field_name: f"Expected datetime for field {field_name}"})

        if expected_type is date:
            if isinstance(value, date) and not isinstance(value, datetime):
                return value
            if isinstance(value, str):
                try:
                    return date.fromisoformat(value)
                except ValueError:
                    raise ValidationError({field_name: f"Invalid date format for field {field_name}"})
            raise ValidationError({field_name: f"Expected date for field {field_name}"})

        # Handle nested models
        if is_dataclass(expected_type) and issubclass(expected_type, BaseModel):
            if not isinstance(value, dict):
                raise ValidationError({field_name: f"Expected an object for field {field_name}"})
            try:
                return expected_type.from_dict(value)
            except ValidationError as e:
                raise ValidationError({field_name: f"Invalid nested object: {e.errors}"})

        # Handle basic types
        if expected_type is int:
            if isinstance(value, bool):
                raise ValidationError({field_name: f"Expected integer for field {field_name}"})
            if isinstance(value, (int, float)):
                if isinstance(value, float) and not value.is_integer():
                    raise ValidationError({field_name: f"Expected integer for field {field_name}"})
                return int(value)
            if isinstance(value, str):
                try:
                    return int(value)
                except ValueError:
                    raise ValidationError({field_name: f"Invalid integer format for field {field_name}"})
            raise ValidationError({field_name: f"Expected integer for field {field_name}"})

        if expected_type is float:
            if isinstance(value, bool):
                raise ValidationError({field_name: f"Expected float for field {field_name}"})
            if isinstance(value, (int, float)):
                return float(value)
            if isinstance(value, str):
                try:
                    return float(value)
                except ValueError:
                    raise ValidationError({field_name: f"Invalid float format for field {field_name}"})
            raise ValidationError({field_name: f"Expected float for field {field_name}"})

        if expected_type is str:
            if not isinstance(value, str):
                raise ValidationError({field_name: f"Expected string for field {field_name}"})
            return value

        if expected_type is bool:
            if isinstance(value, bool):
                return value
            if isinstance(value, str):
                if value.lower() in ('true', '1', 'yes'):
                    return True
                if value.lower() in ('false', '0', 'no'):
                    return False
            raise ValidationError({field_name: f"Expected boolean for field {field_name}"})

        # Fallback: try direct assignment
        if isinstance(value, expected_type):
            return value

        raise ValidationError({field_name: f"Invalid type for field {field_name}. Expected {expected_type.__name__}"})

    @classmethod
    def from_json(cls: Type[T], json_str: str) -> T:
        """Parse and validate a JSON string into a model instance"""
        try:
            data = json.loads(json_str)
        except json.JSONDecodeError as e:
            raise ValidationError({"__root__": f"Invalid JSON: {str(e)}"})
        return cls.from_dict(data)

    def to_dict(self) -> Dict[str, Any]:
        """Convert model to dictionary"""
        result = {}
        for field_info in fields(self):
            value = getattr(self, field_info.name)
            result[field_info.name] = self._serialize_value(value)
        return result

    def to_json(self) -> str:
        """Convert model to JSON string"""
        return json.dumps(self.to_dict(), indent=2, default=str)

    @classmethod
    def _serialize_value(cls, value: Any) -> Any:
        """Serialize a value for JSON output"""
        if isinstance(value, BaseModel):
            return value.to_dict()
        if isinstance(value, list):
            return [cls._serialize_value(item) for item in value]
        if isinstance(value, dict):
            return {str(k): cls._serialize_value(v) for k, v in value.items()}
        if isinstance(value, (datetime, date)):
            return value.isoformat()
        if isinstance(value, Enum):
            return value.value
        return value


