import re
from typing import Optional, Tuple

# Phone number validation patterns
PHONE_PATTERNS = {
    'US': r'^\+?1?[-.\s]?\(?([2-9][0-8][0-9])\)?[-.\s]?([2-9][0-9]{2})[-.\s]?([0-9]{4})$',
    'UK': r'^\+?44[-.\s]?\(?0?[1-9]\d{1,4}\)?[-.\s]?\d{3,4}[-.\s]?\d{3,4}$',
    'DE': r'^\+?49[-.\s]?\(?0?[1-9]\d{1,4}\)?[-.\s]?\d{3,8}$',
    'FR': r'^\+?33[-.\s]?\(?0?[1-9]\)?[-.\s]?\d{2}[-.\s]?\d{2}[-.\s]?\d{2}[-.\s]?\d{2}$',
    'JP': r'^\+?81[-.\s]?\(?0?[1-9]\d{1,4}\)?[-.\s]?\d{1,4}[-.\s]?\d{4}$',
    'AU': r'^\+?61[-.\s]?\(?0?[2-8]\)?[-.\s]?\d{4}[-.\s]?\d{4}$',
    'CA': r'^\+?1[-.\s]?\(?([2-9][0-8][0-9])\)?[-.\s]?([2-9][0-9]{2})[-.\s]?([0-9]{4})$',
    'IN': r'^\+?91[-.\s]?[6-9]\d{9}$',
    'BR': r'^\+?55[-.\s]?\(?[1-9]{2}\)?[-.\s]?9?\d{4}[-.\s]?\d{4}$',
    'RU': r'^\+?7[-.\s]?\(?[1-9]\d{2}\)?[-.\s]?\d{3}[-.\s]?\d{2}[-.\s]?\d{2}$',
}

# Country codes mapping
COUNTRY_CODES = {
    'US': '+1', 'CA': '+1', 'UK': '+44', 'DE': '+49', 'FR': '+33',
    'JP': '+81', 'AU': '+61', 'IN': '+91', 'BR': '+55', 'RU': '+7'
}

def clean_phone_number(phone: str) -> str:
    """Remove all non-digit characters except leading +"""
    phone = phone.strip()
    if phone.startswith('+'):
        return '+' + re.sub(r'\D', '', phone[1:])
    return re.sub(r'\D', '', phone)

def detect_country(phone: str) -> Optional[str]:
    """Detect country based on phone number pattern"""
    cleaned = clean_phone_number(phone)

    # Check for explicit country code
    for country, code in COUNTRY_CODES.items():
        if cleaned.startswith(code.replace('+', '')):
            return country

    # Try to match patterns
    for country, pattern in PHONE_PATTERNS.items():
        if re.match(pattern, phone):
            return country

    return None

def format_international(phone: str, country: Optional[str] = None) -> Tuple[bool, Optional[str], Optional[str]]:
    """
    Validate and format a phone number into international format.

    Returns:
        Tuple of (is_valid, formatted_number, error_message)
    """
    if not phone or not phone.strip():
        return False, None, "Phone number cannot be empty"

    cleaned = clean_phone_number(phone)

    # If country not specified, try to detect it
    if not country:
        country = detect_country(phone)
        if not country:
            return False, None, "Could not detect country from phone number"

    # Validate against country pattern
    pattern = PHONE_PATTERNS.get(country.upper())
    if not pattern:
        return False, None, f"Unsupported country code: {country}"

    if not re.match(pattern, phone):
        return False, None, f"Invalid phone number format for {country.upper()}"

    # Get country code
    country_code = COUNTRY_CODES.get(country.upper())
    if not country_code:
        return False, None, f"No country code mapping for {country.upper()}"

    # Remove leading zeros and country code if present
    local_number = cleaned
    if local_number.startswith(country_code.replace('+', '')):
        local_number = local_number[len(country_code.replace('+', '')):]

    # Remove leading zero for most countries (except some like Italy, etc.)
    if country.upper() not in ['IT'] and local_number.startswith('0'):
        local_number = local_number[1:]

    # Format based on country
    formatted = f"{country_code} {local_number}"

    # Add country-specific formatting
    if country.upper() in ['US', 'CA']:
        if len(local_number) == 10:
            formatted = f"{country_code} ({local_number[:3]}) {local_number[3:6]}-{local_number[6:]}"
    elif country.upper() == 'UK':
        if len(local_number) == 10:
            formatted = f"{country_code} {local_number[:4]} {local_number[4:7]} {local_number[7:]}"
    elif country.upper() == 'DE':
        if len(local_number) >= 10:
            formatted = f"{country_code} {local_number[:3]} {local_number[3:6]} {local_number[6:]}"
    elif country.upper() == 'FR':
        if len(local_number) == 9:
            formatted = f"{country_code} {local_number[:1]} {local_number[1:3]} {local_number[3:5]} {local_number[5:7]} {local_number[7:]}"
    elif country.upper() == 'JP':
        if len(local_number) >= 10:
            formatted = f"{country_code} {local_number[:3]} {local_number[3:6]} {local_number[6:]}"
    elif country.upper() == 'AU':
        if len(local_number) == 9:
            formatted = f"{country_code} {local_number[:1]} {local_number[1:5]} {local_number[5:]}"
    elif country.upper() == 'IN':
        if len(local_number) == 10:
            formatted = f"{country_code} {local_number[:5]} {local_number[5:]}"
    elif country.upper() == 'BR':
        if len(local_number) >= 10:
            formatted = f"{country_code} ({local_number[:2]}) {local_number[2:6]}-{local_number[6:]}"
    elif country.upper() == 'RU':
        if len(local_number) == 10:
            formatted = f"{country_code} ({local_number[:3]}) {local_number[3:6]}-{local_number[6:]}"

    return True, formatted, None

