import threading
import time
import functools
from typing import Any, Callable, Dict, Tuple, Optional

class ThreadSafeTTLCache:
    """Thread-safe TTL cache decorator."""

    def __init__(self, ttl_seconds: float):
        self.ttl_seconds = ttl_seconds
        self._cache: Dict[Tuple, Tuple[Any, float]] = {}
        self._lock = threading.Lock()

    def __call__(self, func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))

            with self._lock:
                # Check cache
                if key in self._cache:
                    result, timestamp = self._cache[key]
                    if time.time() - timestamp < self.ttl_seconds:
                        return result
                    else:
                        del self._cache[key]

            # Compute outside lock to avoid blocking
            result = func(*args, **kwargs)

            with self._lock:
                self._cache[key] = (result, time.time())

            return result

        return wrapper

    def clear(self):
        with self._lock:
            self._cache.clear()

    def get_cache_size(self) -> int:
        with self._lock:
            return len(self._cache)

from functools import lru_cache
import time

def ttl_cache(ttl_seconds):
    def decorator(func):
        @lru_cache(maxsize=128)
        def cached_func(*args, **kwargs):
            return func(*args, **kwargs)

        def wrapper(*args, **kwargs):
            # Check if cache entry exists and is fresh
            cache_key = (args, tuple(sorted(kwargs.items())))
            if cache_key in wrapper._cache_times:
                if time.time() - wrapper._cache_times[cache_key] < ttl_seconds:
                    return cached_func(*args, **kwargs)
                else:
                    # Expired - clear this entry
                    cached_func.cache_clear()
                    wrapper._cache_times.pop(cache_key, None)

            result = cached_func(*args, **kwargs)
            wrapper._cache_times[cache_key] = time.time()
            return result

        wrapper._cache_times = {}
        return wrapper
    return decorator

# Usage
@ttl_cache(ttl_seconds=60)
def expensive_function(x):
    # Simulate expensive operation
    time.sleep(2)
    return x * 2

